sql:
SELECT DISTINCT g.Name
FROM Genre g
ORDER BY g.Name;

SELECT MAX(Track.UnitPrice) AS HighestUnitPrice
FROM Track
GROUP BY Track.TrackId;

SELECT COUNT(*) AS CustomerCount
FROM Customer
WHERE Country = 'Brazil';

SELECT DISTINCT Title
FROM Album
WHERE Title LIKE '%Greatest%';

SELECT AVG(Track.Milliseconds) AS AverageTrackLength
FROM Track
GROUP BY Track.Milliseconds;

SELECT DISTINCT t.Name
FROM Track t
WHERE t.Milliseconds > 1200000;

SELECT COUNT(*) AS InvoiceCount
FROM Invoice
WHERE InvoiceDate >= '2023-01-01' AND InvoiceDate < '2024-01-01';

SELECT DISTINCT MediaTypeId, Name AS MediaType, COUNT(*) AS TrackCount
FROM Track
GROUP BY MediaTypeId, Name;

SELECT DISTINCT E.FirstName, E.LastName, A.Name AS ManagerName
FROM Employee E
LEFT JOIN Artist A ON E.ArtistId = A.ArtistId;

SELECT COUNT(*) AS low_income_count
FROM countries
WHERE income_group = 'Low income';

SELECT DISTINCT country_stats.iso3, COUNT(*) as num_countries
FROM country_stats
GROUP BY country_stats.iso3, country_stats.income_group;

SELECT SUM(CASE WHEN year BETWEEN 2000 AND 2023 THEN population ELSE 0 END) AS total_growth
FROM country_stats
WHERE iso3 = 'CN';

SELECT DISTINCT island
FROM penguins
GROUP BY island;

SELECT COUNT(*) AS unknown_sex_count
FROM penguins
WHERE sex IS NULL;

SELECT species, COUNT(*) AS count
FROM penguins
GROUP BY species;

SELECT AVG(body_mass_g) AS avg_body_mass
FROM penguins
GROUP BY species;

SELECT DISTINCT p.island, p.year, COUNT(DISTINCT p.species) AS penguin_count
FROM penguins p
GROUP BY p.island, p.year;

SELECT MIN(bill_depth_mm) AS min_bill_depth, MAX(bill_depth_mm) AS max_bill_depth
FROM penguins
GROUP BY species;

SELECT AVG(bill_length_mm / bill_depth_mm) AS ratio
FROM penguins
GROUP BY species;
